function.arguments:
{"sql": "SET sqlite_all_varchar=true; 
WITH coord_samples AS (
    SELECT airport_code, coordinates FROM airports_data LIMIT 5
)
SELECT 
    airport_code,
    coordinates,
    CAST(SUBSTR(coordinates, 2, INSTR(coordinates, ',') - 2) AS DOUBLE) as lon,
    CAST(SUBSTR(coordinates, INSTR(coordinates, ',') + 1, LENGTH(coordinates) - INSTR(coordinates, ',') - 2) AS DOUBLE) as lat
FROM coord_samples", "preview_rows": 5}
